function highlightIfInvalid(el, isInvalid) {
  if (!el) return;
  if (isInvalid) {
    el.style.backgroundColor = 'rgba(217, 83, 79, 0.08)';
    el.style.borderColor = '#d9534f';
    el.style.color = '#d9534f';
  } else {
    el.style.backgroundColor = '';
    el.style.borderColor = '';
    el.style.color = '';
  }
}

