function runComparisonSanityChecks() {
  const getValue = (id) => {
    const el = document.getElementById(id);
    return el && el.value !== '' ? Number(el.value) : 0;
  };

  const getElement = (id) => document.getElementById(id);

  // Get headcount baselines from main dashboard
  const emp1Baseline = Math.max(1, Number(getElement('emp1-baseline')?.value) || 50);
  const emp2Baseline = Math.max(1, Number(getElement('emp2-baseline')?.value) || 50);

  // Get baseline annual employee costs from comparison table
  const s1EmpBaselineCost = getValue('comp-s1-emp-baseline');
  const s2EmpBaselineCost = getValue('comp-s2-emp-baseline');

  // 1. Calculate per-employee cost
  const s1PerEmployeeCost = s1EmpBaselineCost / emp1Baseline;
  const s2PerEmployeeCost = s2EmpBaselineCost / emp2Baseline;

  // Format helper
  const formatSalary = (valK) => {
    const full = Math.round(valK * 1000);
    return '£' + full.toLocaleString();
  };

  const s1CostValEl = getElement('sanity-val-s1-emp-cost');
  const s1FormulaEl = getElement('sanity-formula-s1-emp-cost');
  const s2CostValEl = getElement('sanity-val-s2-emp-cost');
  const s2FormulaEl = getElement('sanity-formula-s2-emp-cost');

  if (s1CostValEl) s1CostValEl.textContent = formatSalary(s1PerEmployeeCost);
  if (s1FormulaEl) s1FormulaEl.textContent = `£${s1EmpBaselineCost.toLocaleString()}k / ${emp1Baseline} employees`;
  if (s2CostValEl) s2CostValEl.textContent = formatSalary(s2PerEmployeeCost);
  if (s2FormulaEl) s2FormulaEl.textContent = `£${s2EmpBaselineCost.toLocaleString()}k / ${emp2Baseline} employees`;

  let warningsCount = 0;
  let criticalErrorsCount = 0;

  // Evaluate Per-Employee Cost Check
  const badgeEmpCost = getElement('sanity-badge-emp-cost');
  const alertEmpCost = getElement('sanity-alert-emp-cost');
  let empCostStatus = 'Healthy';
  let empCostAlertText = '';

  // Typical salary range: £10k to £150k
  const s1RevBaseline = scenario1 ? scenario1.getData()[0].value : 4500;
  const s2RevBaseline = scenario2 ? scenario2.getData()[0].value : 4500;

  if (s1PerEmployeeCost <= 0 || s2PerEmployeeCost <= 0) {
    empCostStatus = 'Error';
    empCostAlertText = 'Warning: Baseline cost or employee count is zero or negative. Please enter valid values.';
    criticalErrorsCount++;
  } else if (s1EmpBaselineCost > s1RevBaseline || s2EmpBaselineCost > s2RevBaseline) {
    empCostStatus = 'Error';
    empCostAlertText = 'Warning: Baseline annual employee cost is higher than turnover.';
    criticalErrorsCount++;
  } else if (s1PerEmployeeCost < 12 || s2PerEmployeeCost < 12) {
    empCostStatus = 'Caution';
    empCostAlertText = `Warning: Calculated annual average salary (${formatSalary(Math.min(s1PerEmployeeCost, s2PerEmployeeCost))}) is unusually low (below £12k). Verify that costs are entered in thousands (£k).`;
    warningsCount++;
  } else if (s1PerEmployeeCost > 150 || s2PerEmployeeCost > 150) {
    empCostStatus = 'Caution';
    empCostAlertText = `Warning: Calculated annual average salary (${formatSalary(Math.max(s1PerEmployeeCost, s2PerEmployeeCost))}) is unusually high (above £150k). Verify headcount or costs.`;
    warningsCount++;
  }

  if (badgeEmpCost) {
    badgeEmpCost.textContent = empCostStatus;
    badgeEmpCost.style.background = empCostStatus === 'Healthy' ? '#dff2ef' : (empCostStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeEmpCost.style.color = empCostStatus === 'Healthy' ? '#0b4e53' : (empCostStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertEmpCost) {
    if (empCostAlertText) {
      alertEmpCost.innerHTML = empCostAlertText;
      alertEmpCost.style.display = 'block';
    } else {
      alertEmpCost.style.display = 'none';
    }
  }

  // 2. Baseline Alignment Check
  const s1ProfBaseline = getValue('comp-s1-prof-baseline');
  const s2ProfBaseline = getValue('comp-s2-prof-baseline');

  const mainEmpCostBase = Number(getElement('emp1-cost')?.value) || 0;

  const badgeAlignment = getElement('sanity-badge-alignment');
  const alertAlignment = getElement('sanity-alert-alignment');
  const valAlignmentCost = getElement('sanity-val-alignment-cost');
  const valAlignmentProfit = getElement('sanity-val-alignment-profit');

  let alignmentStatus = 'Healthy';
  let alignmentAlertText = [];

  // Check if Scenario 1 matches Scenario 2 in baselines
  if (s1EmpBaselineCost !== s2EmpBaselineCost) {
    alignmentAlertText.push(`Scenario 1 and Scenario 2 baseline employee costs differ (£${s1EmpBaselineCost}k vs £${s2EmpBaselineCost}k).`);
    alignmentStatus = 'Caution';
  }
  if (s1ProfBaseline !== s2ProfBaseline) {
    alignmentAlertText.push(`Scenario 1 and Scenario 2 baseline net profits differ (£${s1ProfBaseline}k vs £${s2ProfBaseline}k).`);
    alignmentStatus = 'Caution';
  }

  // Check if comparison table matches main dashboard
  if (s1EmpBaselineCost !== mainEmpCostBase) {
    alignmentAlertText.push(`Comparison baseline employee cost (£${s1EmpBaselineCost}k) differs from Main dashboard baseline (£${mainEmpCostBase}k).`);
    alignmentStatus = 'Caution';
  }

  if (valAlignmentCost) {
    valAlignmentCost.textContent = (s1EmpBaselineCost === s2EmpBaselineCost && s1EmpBaselineCost === mainEmpCostBase)
      ? 'Perfect Match'
      : `${s1EmpBaselineCost === s2EmpBaselineCost ? 'S1=S2' : 'S1≠S2'} (Main: £${mainEmpCostBase}k)`;
    valAlignmentCost.style.color = (s1EmpBaselineCost === s2EmpBaselineCost && s1EmpBaselineCost === mainEmpCostBase) ? 'var(--accent)' : '#b45309';
  }

  if (valAlignmentProfit) {
    valAlignmentProfit.textContent = (s1ProfBaseline === s2ProfBaseline) ? 'S1/S2 Aligned' : `Mismatched (S1: £${s1ProfBaseline}k, S2: £${s2ProfBaseline}k)`;
    valAlignmentProfit.style.color = (s1ProfBaseline === s2ProfBaseline) ? 'var(--accent)' : '#b45309';
  }

  if (alignmentStatus === 'Caution') warningsCount++;

  if (badgeAlignment) {
    badgeAlignment.textContent = alignmentStatus;
    badgeAlignment.style.background = alignmentStatus === 'Healthy' ? '#dff2ef' : '#fef3c7';
    badgeAlignment.style.color = alignmentStatus === 'Healthy' ? '#0b4e53' : '#b45309';
  }
  if (alertAlignment) {
    if (alignmentAlertText.length > 0) {
      alertAlignment.innerHTML = 'Warning: ' + alignmentAlertText.join('<br>');
      alertAlignment.style.display = 'block';
    } else {
      alertAlignment.style.display = 'none';
    }
  }

  // 3. Profit Margin Check
  const badgeProfit = getElement('sanity-badge-profit');
  const alertProfit = getElement('sanity-alert-profit');
  const s1MarginEl = getElement('sanity-val-s1-margin');
  const s2MarginEl = getElement('sanity-val-s2-margin');

  const s1RevBaselineVal = scenario1 ? scenario1.getData()[0].value : 4500;
  const s2RevBaselineVal = scenario2 ? scenario2.getData()[0].value : 4500;

  const s1Margin = s1RevBaselineVal ? (s1ProfBaseline / s1RevBaselineVal) * 100 : 0;
  const s2Margin = s2RevBaselineVal ? (s2ProfBaseline / s2RevBaselineVal) * 100 : 0;

  if (s1MarginEl) s1MarginEl.textContent = `${s1Margin.toFixed(1)}%`;
  if (s2MarginEl) s2MarginEl.textContent = `${s2Margin.toFixed(1)}%`;

  let profitStatus = 'Healthy';
  let profitAlertText = '';

  if (s1Margin < 0 || s2Margin < 0) {
    profitStatus = 'Caution';
    profitAlertText = 'Warning: Implied net profit margin is negative. Verify profit/loss values.';
    warningsCount++;
  } else if (s1Margin > 80 || s2Margin > 80) {
    profitStatus = 'Error';
    profitAlertText = 'Warning: Net profit exceeds 80% of revenue. Verify turnover and profit values.';
    criticalErrorsCount++;
  } else if (s1ProfBaseline > (s1RevBaselineVal - s1EmpBaselineCost) || s2ProfBaseline > (s2RevBaselineVal - s2EmpBaselineCost)) {
    profitStatus = 'Error';
    profitAlertText = 'Warning: Net profit cannot be greater than the difference between turnover and employee cost.';
    criticalErrorsCount++;
  } else if (s1Margin > 50 || s2Margin > 50) {
    profitStatus = 'Caution';
    profitAlertText = 'Warning: Net profit margin is exceptionally high (above 50%). Verify numbers.';
    warningsCount++;
  }

  if (badgeProfit) {
    badgeProfit.textContent = profitStatus;
    badgeProfit.style.background = profitStatus === 'Healthy' ? '#dff2ef' : (profitStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeProfit.style.color = profitStatus === 'Healthy' ? '#0b4e53' : (profitStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertProfit) {
    if (profitAlertText) {
      alertProfit.innerHTML = profitAlertText;
      alertProfit.style.display = 'block';
    } else {
      alertProfit.style.display = 'none';
    }
  }

  // 4. GVA & ROI Validation
  const badgeRoi = getElement('sanity-badge-roi');
  const alertRoi = getElement('sanity-alert-roi');
  const totalGvaEl = getElement('sanity-val-total-gva');
  const roiMultEl = getElement('sanity-val-roi-mult');

  const compTotalGva = getValue('comp-total-gva');
  const compProjCost = getValue('comp-project-cost') || 0;
  const roiMultiplier = compProjCost > 0 ? (compTotalGva / compProjCost) : 0;

  if (totalGvaEl) {
    const fullGva = Math.round(compTotalGva * 1000);
    totalGvaEl.textContent = (fullGva < 0 ? '-' : '') + '£' + Math.abs(fullGva).toLocaleString();
  }
  if (roiMultEl) roiMultEl.textContent = compProjCost > 0 ? `${roiMultiplier.toFixed(1)}x` : 'N/A (Cost = 0)';

  let roiStatus = 'Healthy';
  let roiAlertText = '';

  if (compTotalGva < 0) {
    roiStatus = 'Error';
    roiAlertText = 'Warning: Total GVA gain is negative. The intervention under Scenario 2 is generating less GVA than Scenario 1.';
    criticalErrorsCount++;
  } else if (compProjCost > 0 && roiMultiplier < 1) {
    roiStatus = 'Caution';
    roiAlertText = 'Warning: Implied ROI is less than 1.0x. GVA gains do not fully cover the estimated project cost.';
    warningsCount++;
  }

  if (badgeRoi) {
    badgeRoi.textContent = roiStatus;
    badgeRoi.style.background = roiStatus === 'Healthy' ? '#dff2ef' : (roiStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeRoi.style.color = roiStatus === 'Healthy' ? '#0b4e53' : (roiStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertRoi) {
    if (roiAlertText) {
      alertRoi.innerHTML = roiAlertText;
      alertRoi.style.display = 'block';
    } else {
      alertRoi.style.display = 'none';
    }
  }

  // Update Summary Banner
  const summaryBanner = getElement('sanity-summary-banner');
  if (summaryBanner) {
    if (criticalErrorsCount > 0) {
      summaryBanner.style.background = '#fee2e2';
      summaryBanner.style.color = '#991b1b';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><octagon points="7.86 2 16.14 2 22 7.86 22 16.14 16.14 22 7.86 22 2 16.14 2 7.86 7.86 2"></octagon><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>` +
        ` Checks Failed: ${criticalErrorsCount} error(s), ${warningsCount} warning(s)`;
    } else if (warningsCount > 0) {
      summaryBanner.style.background = '#fef3c7';
      summaryBanner.style.color = '#92400e';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg>` +
        ` ${warningsCount} warning(s) detected`;
    } else {
      summaryBanner.style.background = '#d1fae5';
      summaryBanner.style.color = '#065f46';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>` +
        ` All checks passed`;
    }
  }
}

// Standalone CSV Operations
function handleExport() {
  const csv = [];

  function serializeTable(tableId, title) {
    const table = document.getElementById(tableId);
    if (!table) return;
    csv.push(`"${title}"`);
    const rows = table.querySelectorAll('tr');
    for (let i = 0; i < rows.length; i++) {
      const row = [];
      const cols = rows[i].querySelectorAll('td, th');
      for (let j = 0; j < cols.length; j++) {
        const cell = cols[j];
        let cellText = '';
        const numInput = cell.querySelector('input[type="number"]');
        const txtInput = cell.querySelector('input[type="text"]');
        if (numInput) {
          if (tableId === 'summaryTable' && cellText.includes('cost')) {
            cellText = '£' + numInput.value + 'k';
          } else {
            cellText = numInput.value;
          }
        } else if (txtInput) {
          cellText = txtInput.value;
        } else {
          cellText = cell.innerText.replace(/(\r\n|\n|\r)/gm, ' ').trim();
        }
        cellText = '"' + cellText.replace(/"/g, '""') + '"';
        row.push(cellText);
      }
      csv.push(row.join(','));
    }
    csv.push('');
  }

  serializeTable('summaryTable', 'Summary Metrics');

  const s2ForecastTable = document.querySelector('.forecast-table');
  if (s2ForecastTable) {
    csv.push('"Scenario 2 Employment & Skills Forecast"');
    const rows = s2ForecastTable.querySelectorAll('tr');
    for (let i = 0; i < rows.length; i++) {
      const row = [];
      const cols = rows[i].querySelectorAll('td, th');
      for (let j = 0; j < cols.length; j++) {
        const cell = cols[j];
        let cellText = '';
        const numInput = cell.querySelector('input[type="number"]');
        const txtInput = cell.querySelector('input[type="text"]');
        if (numInput) {
          cellText = numInput.value;
        } else if (txtInput) {
          cellText = txtInput.value;
        } else {
          cellText = cell.innerText.replace(/(\r\n|\n|\r)/gm, ' ').trim();
        }
        cellText = '"' + cellText.replace(/"/g, '""') + '"';
        row.push(cellText);
      }
      csv.push(row.join(','));
    }
    csv.push('');
  }

  const s2BandsTable = document.querySelector('.bands-table');
  if (s2BandsTable) {
    csv.push('"Scenario 2 Salary Bands of New Jobs Created"');
    const rows = s2BandsTable.querySelectorAll('tr');
    for (let i = 0; i < rows.length; i++) {
      const row = [];
      const cols = rows[i].querySelectorAll('td, th');
      for (let j = 0; j < cols.length; j++) {
        const cell = cols[j];
        let cellText = '';
        const numInput = cell.querySelector('input[type="number"]');
        if (numInput) {
          cellText = numInput.value;
        } else {
          cellText = cell.innerText.replace(/(\r\n|\n|\r)/gm, ' ').trim();
        }
        cellText = '"' + cellText.replace(/"/g, '""') + '"';
        row.push(cellText);
      }
      csv.push(row.join(','));
    }
    csv.push('');
  }

  csv.push('"Model Inputs"');
  csv.push('"Parameter","Base","Y1","Y2","Y3"');
  csv.push(`"Base Year",${baseYear},,,`);

  const s1Data = scenario1.getData();
  csv.push(`"S1 Revenue",${s1Data.map(d => d.value).join(',')}`);

  const s2Data = scenario2.getData();
  csv.push(`"S2 Revenue",${s2Data.map(d => d.value).join(',')}`);

  const s1Margins = [0, 1, 2, 3].map(i => refreshProfit1.rawMargins[i]);
  csv.push(`"S1 Profit Margin %",${s1Margins.join(',')}`);

  const s2Margins = [0, 1, 2, 3].map(i => refreshProfit2.rawMargins[i]);
  csv.push(`"S2 Profit Margin %",${s2Margins.join(',')}`);

  const s1Emp = [
    document.getElementById('emp1-baseline').value,
    document.getElementById('emp1-y1').value,
    document.getElementById('emp1-y2').value,
    document.getElementById('emp1-y3').value
  ];
  csv.push(`"S1 Employee Count",${s1Emp.join(',')}`);

  const s1EmpCost = document.getElementById('emp1-cost').value;
  csv.push(`"Baseline Employee Cost",${s1EmpCost},,,`);

  const projCost = document.getElementById('project-cost-input').value;
  csv.push(`"Project Cost",${projCost},,,`);

  const s2Upskilled = [1, 2, 3].map(i => document.getElementById(`upskilled-y${i}`).value);
  csv.push(`"S2 Upskilled Count",${s2Upskilled.join(',')},`);

  const s2SkillsNotes = [1, 2, 3].map(i => '"' + document.getElementById(`skills-note-y${i}`).value.replace(/"/g, '""') + '"');
  csv.push(`"S2 Skills Notes",${s2SkillsNotes.join(',')},`);

  for (let b = 0; b < 6; b++) {
    const bandVals = [1, 2, 3].map(yrIdx => {
      const input = document.querySelector(`.band-input[data-band="${b}"][data-year-idx="${yrIdx}"]`);
      return input ? input.value : 0;
    });
    csv.push(`"S2 Band ${b} Count",${bandVals.join(',')},`);
  }
  csv.push('');

  const csvStr = csv.join('\n');
  const blob = new Blob(['\uFEFF' + csvStr], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  link.setAttribute('href', url);
  link.setAttribute('download', 'GVA_Scenario_Modeler_v3_Export.csv');
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

function handleImportClick() {
  document.getElementById('import-file-input').click();
}

function handleImportChange(e) {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (evt) => {
    try {
      const contents = evt.target.result;
      const rows = parseCSV(contents);

      let inputsStartIdx = -1;
      for (let i = 0; i < rows.length; i++) {
        if (rows[i][0] && rows[i][0].trim() === 'Model Inputs') {
          inputsStartIdx = i;
          break;
        }
      }

      if (inputsStartIdx === -1) {
        alert('Could not find "Model Inputs" in the CSV. Please import a valid GVA Scenario Modeler CSV.');
        document.getElementById('import-file-input').value = '';
        return;
      }

      const params = {};
      for (let i = inputsStartIdx + 2; i < rows.length; i++) {
        const r = rows[i];
        if (!r || r.length === 0 || r[0] === '') break;
        const key = r[0].trim();
        const vals = r.slice(1);
        params[key] = vals;
      }

      const requiredKeys = [
        'Base Year', 'S1 Revenue', 'S2 Revenue',
        'S1 Profit Margin %', 'S2 Profit Margin %',
        'S1 Employee Count', 'Baseline Employee Cost', 'Project Cost',
        'S2 Upskilled Count', 'S2 Skills Notes'
      ];
      for (const key of requiredKeys) {
        if (!params[key]) {
          alert(`Missing required parameter "${key}" in the CSV.`);
          document.getElementById('import-file-input').value = '';
          return;
        }
      }

      const importedBaseYear = parseInt(params['Base Year'][0]);
      if (!isNaN(importedBaseYear)) {
        updateBaseYear(importedBaseYear);
      }

      const s1Revs = params['S1 Revenue'].slice(0, 4).map(Number);
      const s2Revs = params['S2 Revenue'].slice(0, 4).map(Number);
      scenario1.setValues(s1Revs);
      scenario2.setValues(s2Revs);
      syncChartScales(s1Revs[0]);

      const s1Emps = params['S1 Employee Count'].slice(0, 4).map(Number);
      document.getElementById('emp1-baseline').value = s1Emps[0];
      document.getElementById('emp1-y1').value = s1Emps[1];
      document.getElementById('emp1-y2').value = s1Emps[2];
      document.getElementById('emp1-y3').value = s1Emps[3];

      document.getElementById('emp1-cost').value = Number(params['Baseline Employee Cost'][0]);

      document.getElementById('emp1-baseline').dispatchEvent(new Event('input'));
      document.getElementById('emp1-cost').dispatchEvent(new Event('input'));

      const upskilled = params['S2 Upskilled Count'].slice(0, 3).map(Number);
      document.getElementById('upskilled-y1').value = upskilled[0];
      document.getElementById('upskilled-y2').value = upskilled[1];
      document.getElementById('upskilled-y3').value = upskilled[2];

      const skillsNotes = params['S2 Skills Notes'].slice(0, 3);
      document.getElementById('skills-note-y1').value = skillsNotes[0] || '';
      document.getElementById('skills-note-y2').value = skillsNotes[1] || '';
      document.getElementById('skills-note-y3').value = skillsNotes[2] || '';

      for (let b = 0; b < 6; b++) {
        const key = `S2 Band ${b} Count`;
        if (params[key]) {
          const vals = params[key].slice(0, 3).map(Number);
          for (let yr = 1; yr <= 3; yr++) {
            const input = document.querySelector(`.band-input[data-band="${b}"][data-year-idx="${yr}"]`);
            if (input) {
              input.value = vals[yr - 1] || 0;
            }
          }
        }
      }

      updateEmployee2();

      const s1Margins = params['S1 Profit Margin %'].slice(0, 4).map(Number);
      const s2Margins = params['S2 Profit Margin %'].slice(0, 4).map(Number);
      for (let i = 0; i < 4; i++) {
        refreshProfit1.rawMargins[i] = s1Margins[i];
        refreshProfit2.rawMargins[i] = s2Margins[i];
      }

      refreshProfit1();
      refreshProfit2();

      const projectCost = Number(params['Project Cost'][0]);
      document.getElementById('project-cost-input').value = projectCost;

      updateSummaryTable();
      alert('Import completed successfully!');
    } catch (err) {
      console.error(err);
      alert('An error occurred while parsing the CSV: ' + err.message);
    }
    document.getElementById('import-file-input').value = '';
  };
  reader.readAsText(file);
}

function parseCSV(text) {
  const lines = [];
  let row = [""];
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];

    if (inQuotes) {
      if (c === '"') {
        if (next === '"') {
          row[row.length - 1] += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        row[row.length - 1] += c;
      }
    } else {
      if (c === '"') {
        inQuotes = true;
      } else if (c === ',') {
        row.push("");
      } else if (c === '\r' || c === '\n') {
        if (c === '\r' && next === '\n') {
          i++;
        }
        lines.push(row);
        row = [""];
      } else {
        row[row.length - 1] += c;
      }
    }
  }
  if (row.length > 1 || row[0] !== "") {
    lines.push(row);
  }
  return lines;
}

// Deferred Dashboard Initialization function
function initializeDashboard() {
  initializeDynamicHeaders();

  scenario1 = createScenarioChart({
    svgId: 'chart1',
    summaryId: 'summary1',
    title: 'Scenario 1',
    series: [
      { label: labels[0], value: 4500 },
      { label: labels[1], value: 5800 },
      { label: labels[2], value: 4300 },
      { label: labels[3], value: 4900 }
    ],
    onUpdate: (data) => {
      if (scenario2) {
        const currentS2Data = scenario2.getData();
        if (currentS2Data[0].value !== data[0].value) {
          scenario2.setDataValue(0, data[0].value);
          syncChartScales(data[0].value);
        }
      }
      refreshProfit1();
      if (typeof updateEmployee1 === 'function') {
        updateEmployee1();
      }
    }
  });

  scenario2 = createScenarioChart({
    svgId: 'chart2',
    summaryId: 'summary2',
    title: 'Scenario 2',
    series: [
      { label: labels[0], value: 4500 },
      { label: labels[1], value: 4600 },
      { label: labels[2], value: 6000 },
      { label: labels[3], value: 5000 }
    ],
    onUpdate: (data) => {
      if (scenario1) {
        const currentS1Data = scenario1.getData();
        if (currentS1Data[0].value !== data[0].value) {
          scenario1.setDataValue(0, data[0].value);
          syncChartScales(data[0].value);
        }
      }
      refreshProfit2();
      updateEmployee2();
    }
  });

  refreshProfit1 = createProfitControls({
    containerId: 'profitGrid1',
    scenarioKey: 's1',
    scenarioName: 'Scenario 1',
    defaultPercents: [10, 15, 20, 22],
    getScenarioData: scenario1.getData
  });

  refreshProfit2 = createProfitControls({
    containerId: 'profitGrid2',
    scenarioKey: 's2',
    scenarioName: 'Scenario 2',
    defaultPercents: [10, 16, 24, 28],
    getScenarioData: scenario2.getData
  });

  updateEmployee1 = createEmployeeLogic('emp1', 's1');

  document.querySelectorAll('.band-input').forEach(input => {
    input.addEventListener('input', updateEmployee2);
  });
  ['1', '2', '3'].forEach(idx => {
    document.getElementById(`upskilled-y${idx}`).addEventListener('input', updateEmployee2);
    document.getElementById(`emp1-y${idx}`).addEventListener('input', () => syncCountToBands(idx));
    document.getElementById(`emp2-y${idx}`).addEventListener('input', () => syncCountToBands(idx));
  });
  document.getElementById('emp2-baseline').addEventListener('input', updateEmployee2);
  document.getElementById('emp2-cost').addEventListener('input', updateEmployee2);

  updateEmployee2();

  document.getElementById('profitGrid1-percent-input-0').addEventListener('input', syncProfitBaseline);
  const amt1 = document.getElementById('profitGrid1-amount-input-0');
  if (amt1) {
    amt1.addEventListener('input', () => {
      setTimeout(syncProfitBaseline, 0);
    });
  }

  document.getElementById('emp1-baseline').addEventListener('input', (e) => syncEmpBaseline(e, 'emp2-baseline'));
  document.getElementById('emp1-cost').addEventListener('input', (e) => syncEmpBaseline(e, 'emp2-cost'));

  const pcInput = document.getElementById('project-cost-input');
  if (pcInput) pcInput.addEventListener('input', updateSummaryTable);

  // Bind Export/Import
  document.getElementById('export-btn').addEventListener('click', handleExport);
  document.getElementById('import-btn').addEventListener('click', handleImportClick);
  document.getElementById('import-file-input').addEventListener('change', handleImportChange);

  // Bind Modal
  document.getElementById('modal-apply-btn').addEventListener('click', handleApplyBaseline);
  document.getElementById('modal-skip-btn').addEventListener('click', handleSkipBaseline);
  document.getElementById('edit-baseline-btn').addEventListener('click', showBaselineModal);
  ['modal-revenue', 'modal-profit', 'modal-emp-cost'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener('input', validateBaselineModalInputs);
    }
  });

  // Load saved comparison state and bind listeners
  loadComparisonState();
  COMP_KEYS.forEach(key => {
    const el = document.getElementById(key);
    if (el) {
      el.addEventListener('input', updateComparisonCalculations);
    }
  });
  updateComparisonCalculations();

  const clearCompBtn = document.getElementById('clear-comparison-btn');
  if (clearCompBtn) {
    clearCompBtn.addEventListener('click', clearComparisonInputs);
  }

  // Restore sidebar collapsed state
  const sidebarCollapsed = sessionStorage.getItem('gva_sidebar_collapsed') === 'true';
  if (sidebarCollapsed) {
    const wrapper = document.querySelector('.layout-wrapper');
    const btn = document.getElementById('menu-toggle-btn');
    if (wrapper) wrapper.classList.add('sidebar-collapsed');
    if (btn) btn.classList.remove('active');
  }

  // Restore comparison collapsed state
  const compCollapsed = sessionStorage.getItem('gva_comp_collapsed') === 'true';
  if (compCollapsed) {
    const content = document.getElementById('comparison-collapsible-content');
    const icon = document.getElementById('comparison-collapse-icon');
    if (content && icon) {
      content.style.maxHeight = '0px';
      content.style.opacity = '0';
      content.style.pointerEvents = 'none';
      icon.textContent = '+';
    }
  }

  scenario1.refresh();
  scenario2.refresh();
  syncChartScales(4500);
  updateSummaryTable();

  const baselineInitialized = sessionStorage.getItem('gva_baseline_initialized') === 'true';
  if (!baselineInitialized) {
    setTimeout(showBaselineModal, 300);
  }
}

// Initialize Authentication Check
checkAuth();


function showInfoModal() {
  const modal = document.getElementById('infoModal');
  if (modal) modal.classList.add('active');
}

function hideInfoModal() {
  const modal = document.getElementById('infoModal');
  if (modal) modal.classList.remove('active');
}


function copySummaryToComparison() {
  const columns = ['baseline', 'y1', 'y2', 'y3'];
  columns.forEach((col, i) => {
    const s1Emp = document.getElementById(`comp-s1-emp-${col}`);
    const s1Prof = document.getElementById(`comp-s1-prof-${col}`);
    const s2Emp = document.getElementById(`comp-s2-emp-${col}`);
    const s2Prof = document.getElementById(`comp-s2-prof-${col}`);

    if (s1Emp) s1Emp.value = Number((employeeCostK.s1[i] || 0).toFixed(2));
    if (s1Prof) s1Prof.value = Number((netProfitK.s1[i] || 0).toFixed(2));
    if (s2Emp) s2Emp.value = Number((employeeCostK.s2[i] || 0).toFixed(2));
    if (s2Prof) s2Prof.value = Number((netProfitK.s2[i] || 0).toFixed(2));
  });

  const projCostEl = document.getElementById('project-cost-input');
  const compProjCostEl = document.getElementById('comp-project-cost');
  if (projCostEl && compProjCostEl) {
    compProjCostEl.value = projCostEl.value;
  }

  updateComparisonCalculations();
}
